// AULA via Home Assistant REST API
//
// Calls the aula.api_call service on Home Assistant, which uses the
// integration's active MitID-authenticated session — no token management needed.
//
// HA service: aula.api_call (supports_response=ONLY)
//   uri      — AULA API query string, e.g. '?method=messaging.getThreads&...'
//   post_data — JSON string for POST requests (omit for GET)
//
// Required env vars:
//   HA_URL   — Home Assistant base URL, e.g. http://192.168.1.240:8123
//   HA_TOKEN — Long-Lived Access Token (HA: Profile → Security → Long-Lived Access Tokens)
//
// Output: msg.payload = { timestamp, threadCount, unreadCount, threads[] }

const HA_URL = (env.get('HA_URL') || 'http://homeassistant.local:8123').replace(/\/$/, '');
const HA_TOKEN = env.get('HA_TOKEN');
const MAX_PAGES = 20; // Safety cap against runaway pagination

if (!HA_TOKEN) {
    node.error(
        'Missing HA_TOKEN. Create a Long-Lived Token in Home Assistant: ' +
        'Profile → Security → Long-Lived Access Tokens.',
        msg
    );
    node.status({ fill: 'red', shape: 'ring', text: 'No HA_TOKEN' });
    return;
}

const SERVICE_URL = HA_URL + '/api/services/aula/api_call?return_response';
const HEADERS = {
    'Authorization': 'Bearer ' + HA_TOKEN,
    'Content-Type': 'application/json'
};

/**
 * Call aula.api_call via HA REST API and return the AULA response object.
 * HA wraps the service return value as { service_response: <data> }.
 */
async function aulaGet(uri) {
    const res = await fetch(SERVICE_URL, {
        method: 'POST',
        headers: HEADERS,
        body: JSON.stringify({ uri: uri })
    });
    if (!res.ok) {
        const txt = await res.text();
        throw new Error(
            'HA aula.api_call failed (HTTP ' + res.status + '): ' + txt.slice(0, 300)
        );
    }
    const body = await res.json();
    // HA wraps response as { service_response: <actual_aula_response> }
    const aula = body.service_response !== undefined ? body.service_response : body;
    if (aula.raw_response) {
        // custom_api_call returns { raw_response: '...' } when AULA sends non-JSON
        throw new Error('AULA returned non-JSON: ' + String(aula.raw_response).slice(0, 200));
    }
    return aula;
}

async function fetchAllThreads() {
    const threads = [];
    for (let page = 0; page < MAX_PAGES; page++) {
        const uri = '?method=messaging.getThreads&sortOn=date&orderDirection=desc&page=' + page;
        node.status({ fill: 'blue', shape: 'dot', text: 'Threads p' + page + '...' });
        const res = await aulaGet(uri);
        if (!res.data || !res.data.threads) {
            throw new Error(
                'Unexpected getThreads response on page ' + page + ': ' +
                JSON.stringify(res).slice(0, 200)
            );
        }
        const pageThreads = res.data.threads;
        threads.push.apply(threads, pageThreads);
        node.status({ fill: 'blue', shape: 'dot', text: 'Threads p' + page + ' (' + threads.length + ')' });
        if (pageThreads.length < 10) break; // Fewer than 10 = last page
    }
    return threads;
}

async function fetchMessagesForThread(threadId) {
    const messages = [];
    for (let page = 0; page < MAX_PAGES; page++) {
        const uri = '?method=messaging.getMessagesForThread&threadId=' + threadId + '&page=' + page;
        const res = await aulaGet(uri);
        if (!res.data || !res.data.messages || res.data.messages.length === 0) break;
        messages.push.apply(messages, res.data.messages);
        if (res.data.messages.length < 20) break; // Fewer than 20 = last page
    }
    return messages;
}

(async function () {
    try {
        node.status({ fill: 'blue', shape: 'ring', text: 'Henter via HA...' });
        const threads = await fetchAllThreads();

        const enrichedThreads = [];
        for (let i = 0; i < threads.length; i++) {
            node.status({ fill: 'blue', shape: 'dot', text: 'Beskeder ' + (i + 1) + '/' + threads.length });
            const messages = await fetchMessagesForThread(threads[i].id);
            enrichedThreads.push({ thread: threads[i], messages: messages });
        }

        const unreadCount = threads.filter(function (t) { return !t.read; }).length;
        msg.payload = {
            timestamp: new Date().toISOString(),
            threadCount: threads.length,
            unreadCount: unreadCount,
            threads: enrichedThreads
        };

        node.status({
            fill: 'green', shape: 'dot',
            text: threads.length + ' tråde, ' + unreadCount + ' ulæste'
        });
        node.send(msg);
    } catch (err) {
        node.error('HA/AULA fejl: ' + err.message, msg);
        node.status({ fill: 'red', shape: 'ring', text: err.message.slice(0, 50) });
    }
})();

// AULA MQTT Formatter
// Converts raw AULA thread data into per-topic MQTT messages.
// Returns an array so Node-RED sends each element as a separate message.
//
// Published topics (relative to PREFIX):
//   {PREFIX}          — full thread summary (retained)
//   {PREFIX}/status   — heartbeat with thread/unread counts (retained)
//   {PREFIX}/{id}     — per-thread detail with full message text (retained)
//   {PREFIX}/unread   — list of unread threads only (NOT retained)
//
// Optional env vars:
//   MQTT_TOPIC_PREFIX — topic prefix (default: 'aula/messages')

const PREFIX = env.get('MQTT_TOPIC_PREFIX') || 'aula/messages';
const data = msg.payload;

if (!data || !data.threads) {
    node.warn('No AULA thread data to publish');
    return null;
}

function stripHtml(html) {
    if (!html) return '';
    return String(html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

const out = [];

// 1. Status heartbeat — always published so HA sensors stay fresh
out.push({
    topic: PREFIX + '/status',
    payload: JSON.stringify({
        timestamp: data.timestamp,
        threadCount: data.threadCount,
        unreadCount: data.unreadCount
    }),
    qos: 1,
    retain: true
});

// 2. Summary of all threads
out.push({
    topic: PREFIX,
    payload: JSON.stringify({
        timestamp: data.timestamp,
        threadCount: data.threadCount,
        unreadCount: data.unreadCount,
        threads: data.threads.map(function (item) {
            return {
                id: item.thread.id,
                subject: item.thread.subject || '',
                read: item.thread.read || false,
                messageCount: item.messages.length
            };
        })
    }),
    qos: 1,
    retain: true
});

// 3. Per-thread detail with full message text
data.threads.forEach(function (item) {
    var t = item.thread;
    var formatted = item.messages
        .filter(function (m) { return !m.messageType || m.messageType === 'Message'; })
        .map(function (m) {
            var text = '';
            try {
                text = (m.text && m.text.html)
                    ? stripHtml(m.text.html)
                    : stripHtml(String(m.text || ''));
            } catch (e) { text = ''; }
            return {
                id: m.id,
                sendDateTime: m.sendDateTime,
                sender: (m.sender && m.sender.fullName) ? m.sender.fullName : 'Unknown',
                text: text,
                messageType: m.messageType || 'Message'
            };
        });
    out.push({
        topic: PREFIX + '/' + t.id,
        payload: JSON.stringify({
            id: t.id,
            subject: t.subject || '',
            read: t.read || false,
            messageCount: formatted.length,
            messages: formatted
        }),
        qos: 1,
        retain: true
    });
});

// 4. Unread-only list — not retained, useful for triggering HA automations
var unread = data.threads.filter(function (item) { return !item.thread.read; });
if (unread.length > 0) {
    out.push({
        topic: PREFIX + '/unread',
        payload: JSON.stringify({
            timestamp: data.timestamp,
            count: unread.length,
            threads: unread.map(function (item) {
                return { id: item.thread.id, subject: item.thread.subject || '' };
            })
        }),
        qos: 0,
        retain: false
    });
}

// Return array: Node-RED sends each element as a separate message to output 0
return [out];
